        if (arg && (name === "$scope" || (isGen && arg.params.length > 0))) {
          context.report({
            node,
            messageId: "row",
            data: { name },
            fix: fixer => fixer.replaceText(node, argText)
          });
          return;
        }
        if (!isGen) {
          unfixed.add(name);
          context.report({ node, messageId: "other" });
          return;
        }
