      "Program:exit"() {
        for (const decl of imports) {
          const specs = decl.specifiers.filter(
            s =>
              s.type === "ImportSpecifier" &&
              s.imported.type === "Identifier" &&
              (s.imported.name === "$" || s.imported.name === "$scope")
