              context.report({
                node,
                messageId: "read",
                data: { key },
                fix:
                  p.kind === "init"
                    ? fixer => fixer.replaceText(p.value, propValue(source, p.value))
                    : null
              });
            }
            return;
          }
          child = p;
          p = p.parent;
        }
      }
    };
  }
};

/**
