          if (node.kind !== "init" || (v.type !== "JSXElement" && v.type !== "JSXFragment")) return;
          context.report({
            node,
            messageId: "fallback",
            data: { name: call.callee.name },
            fix: fixer =>
              fixer.replaceText(node, `fallback: function* () {\nreturn ${source.getText(v)};\n}`)
          });
