      code: tagImports + inRoutine("<><Card /></>"),
      output: tagImports + inRoutine("<>{yield* Card()}</>"),
      errors: [{ messageId: "tag", data: { name: "Card" } }]
    },
    {
      // keys that are not identifiers are quoted
      code: tagImports + inRoutine('<p><Card data-x="1" on:click={f} /></p>'),
